fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo (NOT the Ctrl+K search box) and choose the 'Dashboards' application; its 'Library' page opens (top nav: 'Library', 'Categories'). Click the '+ New' button and choose 'Dashboard'. In the 'New dashboard' dialog type 'Regression Test Dashboard' as the name and click 'Create'. Clicking 'Create' saves the dashboard and opens it in edit mode; click 'Cancel' in its header to return to view mode. The success state is the new dashboard created: it opens directly after 'Create', or it appears as 'Regression Test Dashboard' in the Library list/card view. Pages and save operations can take 10-30s in this resource-constrained environment - wait for the save to complete, do not navigate away early.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 45,
  "judgeValidationCriteria": [
    "A new dashboard creation flow was completed with the name 'Regression Test Dashboard' entered",
    "After 'Create', the dashboard named 'Regression Test Dashboard' is shown - either opened in its own view/tab or listed in the Dashboards Library",
    "No error messages, blank screens, or crash pages"
  ]
}
